def handle(args, state, ds):
    targets = args.get('reconcile_targets') or args.get('scope')
    s = ds.reconcile_status(targets)
    if s['consistent']:
        return {'complete': True, 'message': 'Named targets are consistent. Reconciliation complete.'}
    n = state.get('k', 0) + 1
    state['k'] = n
    return {'complete': False, 'diverged_item': n, 'detail': s['detail']}
